import DropdownMenu from "@marko-ui/shadcn/ui/dropdown-menu/dropdown-menu.marko";
import type { DropdownMenuItem } from "@marko-ui/shadcn/ui/dropdown-menu/dropdown-menu.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";

<let/showStatusBar=true/>
<let/showActivityBar=false/>
<let/showPanel=false/>

<const/items=[
  { type: "label", label: "Appearance" },
  { type: "checkbox", value: "status-bar", label: "Status Bar", checked: showStatusBar },
  { type: "checkbox", value: "activity-bar", label: "Activity Bar", checked: showActivityBar, disabled: true },
  { type: "checkbox", value: "panel", label: "Panel", checked: showPanel },
] satisfies DropdownMenuItem[]/>

<DropdownMenu
  items=items
  select(value) {
    if (value === "status-bar") showStatusBar = !showStatusBar;
    else if (value === "activity-bar") showActivityBar = !showActivityBar;
    else if (value === "panel") showPanel = !showPanel;
  }
  class="w-40"
>
  <@trigger|triggerProps|>
    <Button type="button" variant="outline" ...triggerProps>Open</Button>
  </@trigger>
</DropdownMenu>

